events=[]
def decorate():
 events.append('decorator')
 def apply(f):
  events.append('apply')
  assert f.__annotations__=={'x':int,'return':int}
  return f
 return apply
def value(name):
 events.append(name)
 return 3 if name=='default' else int
@decorate()
def values(x:value('annotation')=value('default'))->value('return'):
 yield x
print(next(values()),events)
